// Macro teaching models use percentage inputs and explicit frequency/unit conventions.
const n=x=>(Math.abs(x)<.0000001?0:x).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct=x=>n(x*100)+'%';
const f=(label,key,value,min=-100,max=100,unit='%')=>({label,key,value,min,max,unit});
const lab=(title,fields,run,note,extra={})=>({title,fields,run,note,...extra});
export function macroRegime(d){const growth=d.growth-d.previousGrowth,inflation=d.inflation-d.previousInflation;return {growth,inflation,name:Math.abs(growth)<1e-10||Math.abs(inflation)<1e-10?'边界状态：至少一项动能持平':growth>0?(inflation>0?'再通胀型环境':'金发姑娘环境'):(inflation>0?'滞胀型环境':'通胀回落型放缓')};}
export function macroGrowth(d){if(![1,4,12].includes(d.frequency))throw Error('比较频率须为年度、季度或月度。');return {period:d.current/d.previous-1,annual:(d.current/d.previous)**d.frequency-1};}
export function macroCrossAsset(d){const dy=d.shock/10000,k=d.discount/100,g=d.growth/100,next=k+dy*d.pass/100;if(k<=g||next<=g)throw Error('变化前及变化后的股票折现率都必须大于长期股息增长率。');return {bond:-d.duration*dy,before:d.dividend/(k-g),after:d.dividend/(next-g),stock:(k-g)/(next-g)-1};}
export function macroScenario(d){const p=[d.softProbability,d.recessionProbability,d.inflationProbability].map(x=>x/100),r=[d.softReturn,d.recessionReturn,d.inflationReturn].map(x=>x/100);if(Math.abs(p.reduce((a,b)=>a+b,0)-1)>1e-8)throw Error('三种情景概率之和必须为100%。');const mean=p.reduce((s,x,i)=>s+x*r[i],0),variance=p.reduce((s,x,i)=>s+x*(r[i]-mean)**2,0);return {mean,variance,sd:Math.sqrt(variance),lossProbability:p.reduce((s,x,i)=>s+(r[i]<0?x:0),0),pnl:d.nav*mean};}
const scoreFields=[f('制造业PMI标准分数','pmi',-1.2,-10,10,'σ'),f('工业生产标准分数','production',-.5,-10,10,'σ'),f('实际零售销售标准分数','retail',.4,-10,10,'σ'),f('新增就业标准分数','employment',.2,-10,10,'σ'),f('消费者信心标准分数','confidence',-.8,-10,10,'σ')];
const weights=[.25,.2,.2,.2,.15];
export const macroComposite=d=>scoreFields.reduce((s,f,i)=>s+d[f.key]*weights[i],0);
const chart=(body,w=600,h=260)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}">${body}</svg>`;
export const macroLabs={
 macroregime:lab('宏观经济状态识别',[f('上一期GDP增速','previousGrowth',2.5),f('当前GDP增速','growth',1.5),f('上一期通胀率','previousInflation',4),f('当前通胀率','inflation',2.5)],d=>{const x=macroRegime(d);return [['增长动能变化',n(x.growth)+' 个百分点'],['通胀动能变化',n(x.inflation)+' 个百分点'],['模型识别',x.name]];},'仅比较两个时期的增速，不能独立判定经济衰退。原课“通缩型放缓”在这里明确为“通胀回落型放缓”；正通胀回落仍可能伴随物价上涨。',{figure:d=>{const x=macroRegime(d),px=300+Math.max(-10,Math.min(10,x.growth))*22,py=130-Math.max(-10,Math.min(10,x.inflation))*9;return chart('<rect x="40" y="25" width="260" height="105" fill="#fce5df"/><rect x="300" y="25" width="260" height="105" fill="#fff0ce"/><rect x="40" y="130" width="260" height="105" fill="#e4edf8"/><rect x="300" y="130" width="260" height="105" fill="#e0f3e9"/><path d="M300 25 V235 M40 130 H560" stroke="#788a83"/><text x="60" y="50">滞胀：增长减速、通胀上行</text><text x="315" y="50">再通胀：增长加速、通胀上行</text><text x="60" y="220">增长减速、通胀回落</text><text x="315" y="220">金发姑娘：增长加速、通胀回落</text><circle cx="'+px+'" cy="'+py+'" r="8" fill="#173f35"/><text x="300" y="255" text-anchor="middle">横轴：增长动能；纵轴：通胀动能（百分点，位置限幅）</text>');}}),
 macrogrowth:lab('经济增长率与复合年化转换',[{...f('比较频率','frequency',4,1,12,''),options:[[12,'月度'],[4,'季度'],[1,'年度']]},f('上一期正值水平','previous',100,.000001,1e12,'指数或同一单位'),f('当前正值水平','current',102,.000001,1e12,'指数或同一单位')],d=>{const x=macroGrowth(d);return [['本期增长率',pct(x.period)],['复合年化增长率',pct(x.annual)]];},'年化＝(当前水平÷上一期水平)^每年期数－1。适用于正值水平数据；年化是假设当前速度持续一年，不是预测，不能把已计算的增长率作为水平输入。'),
 macrozscore:lab('宏观指标标准化',[f('当前指标值','value',48,-1e9,1e9,'原指标单位'),f('历史平均值','mean',52,-1e9,1e9,'原指标单位'),f('历史标准差','sd',2,.000001,1e9,'原指标单位')],d=>[['Z-score',n((d.value-d.mean)/d.sd)+' σ'],['偏离历史均值',n(d.value-d.mean)+' 原指标单位']],'Z＝(当前值－历史均值)÷历史标准差。参考正态曲线不代表真实数据服从正态分布，偏离均值不自动等于衰退。',{figure:d=>{const z=(d.value-d.mean)/d.sd,x=z=>300+z*62,points=Array.from({length:121},(_,i)=>{const t=-4+8*i/120;return (i?'L':'M')+x(t)+' '+(220-Math.exp(-t*t/2)*175);}).join(' ');return chart('<path d="M52 220 H548" stroke="#87968e"/><path d="'+points+'" fill="none" stroke="#278164" stroke-width="3"/><line x1="'+x(Math.max(-4,Math.min(4,z)))+'" x2="'+x(Math.max(-4,Math.min(4,z)))+'" y1="35" y2="220" stroke="#cc6b44" stroke-width="2"/><text x="300" y="252" text-anchor="middle">标准正态参考曲线；当前 Z='+n(z)+'（标记限于±4）</text>');}}),
 macrocomposite:lab('宏观经济综合评分',scoreFields,d=>[['综合经济评分',n(macroComposite(d))],['相对历史参考水平',macroComposite(d)<0?'低于历史参考水平':macroComposite(d)>0?'高于历史参考水平':'等于历史参考水平']],'固定教学权重：25%、20%、20%、20%、15%。负分不等于GDP负增长；权重、阈值未做历史回测或样本外验证。',{table:d=>({headers:['指标','权重','标准分数','评分贡献'],rows:scoreFields.map((f,i)=>[f.label.replace('标准分数',''),pct(weights[i]),n(d[f.key]),n(d[f.key]*weights[i])])})}),
 macrosurprise:lab('经济数据预期差',[{...f('指标类型','indicator',0,0,2,''),options:[[0,'CPI同比'],[1,'GDP增速'],[2,'失业率']]},f('实际公布值','actual',3.2),f('市场一致预期','consensus',3.5),f('历史预测误差标准差','sd',.2,.000001,100,'个百分点')],d=>{if(![0,1,2].includes(d.indicator))throw Error('请选择有效指标类型。');const gap=d.actual-d.consensus;return [['经济意外值',n(gap)+' 个百分点'],['标准化意外值',n(gap/d.sd)+' σ'],['经济含义',Math.abs(gap)<1e-10?'符合市场一致预期':d.indicator===0?(gap<0?'通胀低于预期':'通胀高于预期'):d.indicator===1?(gap<0?'增长弱于预期':'增长强于预期'):(gap<0?'失业率低于预期':'失业率高于预期')]];},'意外值＝实际－预期；标准化分母为历史预测误差标准差。失业率的经济方向与增长不同，市场反应还取决于修订、细项、政策、估值及仓位。'),
 macrocrossasset:lab('利率变化与跨资产定价',[f('市场债券收益率变化','shock',-50,-2000,2000,'基点'),f('债券修正久期','duration',7,0,100,'年'),f('股票初始折现率','discount',9,-50,100),f('长期股息增长率','growth',3,-50,100),f('下一期每股股息','dividend',5,.000001,1e9,'英镑'),f('向股票折现率传导比例','pass',100,0,100)],d=>{const x=macroCrossAsset(d);return [['债券价格一阶近似变化',pct(x.bond)],['股票理论估值变化',pct(x.stock)],['变化前股票理论价值','£'+n(x.before)],['变化后股票理论价值','£'+n(x.after)]];},'1基点＝0.0001；债券变化≈－修正久期×收益率变化，忽略凸性与信用利差。股票采用D₁/(k－g)，其他条件不变；大幅冲击时债券一阶近似可能失效。'),
 macroscenario:lab('全球宏观情景投资收益',[f('软着陆概率','softProbability',50,0,100),f('经济衰退概率','recessionProbability',30,0,100),f('通胀反弹概率','inflationProbability',20,0,100),f('软着陆情景收益','softReturn',8,-100,1000),f('经济衰退情景收益','recessionReturn',-10,-100,1000),f('通胀反弹情景收益','inflationReturn',-5,-100,1000),f('组合资产规模','nav',1000,0,1e9,'百万美元')],d=>{const x=macroScenario(d);return [['概率加权预期收益',pct(x.mean)],['情景收益标准差',pct(x.sd)],['设定情景中的亏损概率',pct(x.lossProbability)],['组合预期损益',n(x.pnl)+' 百万美元']];},'概率必须合计100%，不自动归一化。默认资产规模1000百万美元＝10亿美元。结果依赖主观情景，情景标准差不是日收益序列计算的年化波动率。')
};
